# reverse/trim/reverse:
rev1 <- function(x,n=100,m=5){
   for(i in 1:n){
     y=rev(rev(x)[-(1:m)])
   }
   return(y)
}

# get length, trim
rev2 <- function(x,n=100,m=5){
   for(i in 1:n){
     y=x[1:(length(x)-m)]
   }
   return(y)
}

  > system.time(rev1(1:1000,10000,5))
